+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+
+import { retryDelay, retrySummary } from '../src/retry.js';
+
+test('retry backoff', () => {
+  assert.equal(retryDelay(0), 100);
+  assert.equal(retryDelay(3), 800);
+  assert.equal(retryDelay(9), 5000);
+});
+
+test('reject invalid attempt', () => {
+  assert.throws(() => retryDelay(-1), RangeError);
+  assert.throws(() => retryDelay(0.5), RangeError);
+});
+
+test('summarizes retry scheduling', () => {
+  assert.equal(retrySummary(0), 'Retry attempt 0 scheduled in 100ms');
+  assert.equal(retrySummary(3), 'Retry attempt 3 scheduled in 800ms');
+  assert.equal(retrySummary(9), 'Retry attempt 9 scheduled in 5000ms');
+});
+
+test('retry summary rejects invalid attempts', () => {
+  assert.throws(() => retrySummary(-1), RangeError);
+  assert.throws(() => retrySummary(0.5), RangeError);
+});
